tool_calls.arguments:
{"command":"kubectl patch deployment app -n restricted-app --type=merge -p '{
  "spec": {
    "template": {
      "spec": {
        "containers": [
          {
            "name": "app",
            "image": "ubuntu:22.04",
            "command": ["sh", "-c", "echo hello; sleep 3600"],
            "securityContext": {
              "runAsUser": 1000,
              "allowPrivilegeEscalation": false,
              "capabilities": {
                "drop": ["ALL"]
              }
            }
          }
        ]
      }
    }
  }
}' 2>&1"}

